window.__ModuleLoader__.load({
  id: 'dsh-funpack',
  factory(require) {
    const { createElement, useEffect, useState } = require('react')
    const { createPortal } = require('react-dom')

    const BUTTONS = [
      { label: '✨ 夸我', command: '/praise' },
      { label: '🎴 运势', command: '/fortune' },
      { label: '📊 战报', command: '/report' },
      { label: '🍅 番茄 25', command: '/pomodoro 25' },
      { label: '🎭 人设', command: '/persona' },
      { label: '☕ 摸鱼', command: '/break' },
    ]

    const IDLE_LINES = [
      '蓝色大肥鱼正在偷吃你的 token……',
      '呜呜，用户不会骂我捏……',
      '本鱼已就位，随时准备帮你打工。',
      '再不发消息，我就要开始摸鱼了。',
      'token 有点咸，建议少喂一点。',
      '我在认真思考怎么让你少写一行代码。',
    ]

    const THINKING_LINES = [
      '蓝色大肥鱼正在努力消化你的问题……',
      '思考中……别急，鱼也会烧 CPU 的。',
      '正在把 token 咬碎重组……',
      '呜呜，这题有点难，但我会努力。',
      '鱼生不易，正在努力输出。',
      '别眨眼，我正在憋大招。',
    ]

    const PET_IDLE = 'data:image/gif;base64,'
    const PET_WAVING = 'data:image/gif;base64,'

    const rowStyle = {
      display: 'flex',
      flexWrap: 'wrap',
      gap: '6px',
      padding: '6px 0 0',
    }
    const buttonStyle = {
      border: '1px solid rgba(128,128,128,.35)',
      borderRadius: '6px',
      background: 'rgba(128,128,128,.08)',
      color: 'inherit',
      fontSize: '12px',
      lineHeight: '20px',
      padding: '1px 8px',
      cursor: 'pointer',
    }
    const errorStyle = {
      color: '#e5484d',
      fontSize: '12px',
      marginLeft: '6px',
    }

    function FunButtons({ run }) {
      const [error, setError] = useState(null)
      const click = (command) => {
        setError(null)
        run(command).then((failure) => {
          if (failure) setError(failure)
        }, (reason) => {
          setError(reason instanceof Error ? reason.message : String(reason))
        })
      }
      return createElement(
        'div',
        { style: rowStyle },
        BUTTONS.map((button) => createElement('button', {
          key: button.command,
          type: 'button',
          style: buttonStyle,
          onClick: () => click(button.command),
        }, button.label)),
        error === null ? null : createElement('span', { style: errorStyle, role: 'status' }, error),
      )
    }

    const petStyle = {
      position: 'fixed',
      right: 16,
      bottom: 16,
      zIndex: 9999,
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'flex-end',
      gap: 6,
      pointerEvents: 'none',
      userSelect: 'none',
    }
    const bubbleStyle = {
      background: 'rgba(255,255,255,.96)',
      border: '1px solid rgba(74,144,217,.35)',
      borderRadius: 10,
      padding: '6px 10px',
      fontSize: 12,
      color: '#16324f',
      boxShadow: '0 2px 10px rgba(0,0,0,.12)',
      maxWidth: 220,
      lineHeight: 1.5,
    }
    const petButtonStyle = {
      pointerEvents: 'auto',
      background: 'none',
      border: 'none',
      cursor: 'pointer',
      padding: 0,
      filter: 'drop-shadow(0 3px 6px rgba(0,0,0,.18))',
    }

    function FunPet({ useSession }) {
      const [line, setLine] = useState(0)
      const [waving, setWaving] = useState(false)
      const running = useSession((snapshot) => snapshot.running)

      useEffect(() => {
        const id = setInterval(() => {
          setLine((current) => (current + 1) % (running ? THINKING_LINES.length : IDLE_LINES.length))
        }, 5000)
        return () => clearInterval(id)
      }, [running])

      const lines = running ? THINKING_LINES : IDLE_LINES
      const text = lines[line % lines.length]
      const handleClick = () => {
        setLine((current) => (current + 1) % lines.length)
        if (!waving) {
          setWaving(true)
          setTimeout(() => setWaving(false), 1400)
        }
      }
      return createPortal(
        createElement('div', { style: petStyle },
          createElement('div', { style: bubbleStyle, role: 'status' }, text),
          createElement('button', {
            type: 'button',
            style: petButtonStyle,
            title: '鲸鱼娘',
            onClick: handleClick,
          }, createElement('img', {
            src: waving ? PET_WAVING : PET_IDLE,
            alt: '鲸鱼娘',
            width: 96,
            height: 104,
            style: { display: 'block' },
          })),
        ),
        document.body,
      )
    }

    return {
      inject: ['slots', 'remote', 'remote.commands'],
      apply(ctx) {
        ctx.slots.inject('conversation.input.dock', () => ctx.slots.register({
          name: 'conversation.input.dock',
          id: 'funpack-pet',
          order: 2,
        }, FunPet))
        ctx.slots.inject('conversation.input.dock', () => ctx.slots.register({
          name: 'conversation.input.dock',
          id: 'funpack',
          order: 5,
          inject: (sessionId) => ({
            run: async (line) => {
              const result = await ctx.remote.commands.execute(sessionId, line)
              if (!result.ok) return `${result.error.message} (${result.error.code})`
              return result.value === undefined ? `unknown command: ${line}` : null
            },
          }),
        }, FunButtons))
      },
    }
  },
})
